from nl import nl_syntax_spec
from InputOutputInfoGeneratorNl import InputOutputInfoGeneratorNl
from ParallelizabilityInfoGeneratorNl import ParallelizabilityInfoGeneratorNl

help_text = subprocess.run(['nl','--help'],capture_output=True,text=True).stdout
# 1. every spelling in the syntax spec appears in --help, and the JSON table agrees with the spec
spec_opts = {}
for node in nl_syntax_spec[0][0]:
    for s in [node.flag]+node.alias:
        assert s in help_text, s
        spec_opts[s] = node.kind
table = json.load(open('/home/tirandagan.guest/naive-arm/output/annotation/nl.json'))
tbl_flags = {s for e in table['flag'] for s in ([e] if isinstance(e,str) else e)}
tbl_opts = {s for e in table['option'] for s in e[:-1]}
assert tbl_flags == {s for s,k in spec_opts.items() if k=='Flag'}, (tbl_flags)
assert tbl_opts == {s for s,k in spec_opts.items() if k!='Flag'}, (tbl_opts)
# every --long option listed in --help is covered
import re
assert set(re.findall(r'--[a-z-]+', help_text)) - {'--help','--version'} <= set(spec_opts), set(re.findall(r'--[a-z-]+', help_text)) - set(spec_opts)
# 2. binary accepts every option spelling with a sample value, rejects invalid Integer/Selection values
samples = {'String':'a','Delimiter':'\\:','Integer':'2','Selection':'rz','Separator':':'}
for s,k in spec_opts.items():
    args = [s] if k=='Flag' else ([s+'='+samples[k]] if s.startswith('--') else [s, samples[k]])
    r = subprocess.run(['nl']+args, input='x\n', capture_output=True, text=True)
    assert r.returncode==0 or s in ('--help','--version'), (args, r.stderr)
for args in (['-w','0'],['-l','0'],['-n','xx'],['-i','1.5'],['-b','z'],['-w','2k']):
    assert subprocess.run(['nl']+args, input='x\n', capture_output=True, text=True).returncode!=0, args
for args in (['-i','-3'],['-v','0'],['-i','0'],['-d',''],['-b','p^x']):
